from getpass import getpass
import json
import os

class ownCloud:
    def __init__(self, base_url, username, password):
        self.base_url = base_url
        self.username = username
        self.password = password
        self.auth = HTTPBasicAuth(username, password)

    def authenticate(self):
        try:
            response = requests.get(f'{self.base_url}/status.json', auth=self.auth)
            if response.status_code == 200:
                return True
            else:
                return False
        except requests.exceptions.RequestException:
            return False

    def upload_file(self, remote_path, local_file):
        try:
            files = {'file': open(local_file, 'rb')}
            response = requests.put(f'{self.base_url}/{remote_path}', files=files, auth=self.auth)
            if response.status_code == 201:
                return True
            else:
                return False
        except requests.exceptions.RequestException:
            return False

    def download_file(self, remote_path, local_file):
        try:
            response = requests.get(f'{self.base_url}/{remote_path}', stream=True, auth=self.auth)
            if response.status_code == 200:
                with open(local_file, 'wb') as f:
                    for chunk in response.iter_content(1024):
                        f.write(chunk)
                return True
            else:
                return False
        except requests.exceptions.RequestException:
            return False

    def list_files(self, path=''):
        try:
            response = requests.get(f'{self.base_url}/files/{path}', auth=self.auth)
            if response.status_code == 200:
                return json.loads(response.text)
            else:
                return []
        except requests.exceptions.RequestException:
            return []

    def create_directory(self, path):
        try:
            response = requests.put(f'{self.base_url}/files/{path}', json={'name': path}, auth=self.auth)
            if response.status_code == 201:
                return True
            else:
                return False
        except requests.exceptions.RequestException:
            return False

    def delete_file(self, path):
        try:
            response = requests.delete(f'{self.base_url}/files/{path}', auth=self.auth)
            if response.status_code == 204:
                return True
            else:
                return False
        except requests.exceptions.RequestException:
            return False

    def move_file(self, source, destination):
        try:
            response = requests.put(f'{self.base_url}/files/{source}/move/{destination}', auth=self.auth)
            if response.status_code == 200:
                return True
            else:
                return False
        except requests.exceptions.RequestException:
            return False

    def get_user_info(self):
        try:
            response = requests.get(f'{self.base_url}/users/self', auth=self.auth)
            if response.status_code == 200:
                return json.loads(response.text)
            else:
                return {}
        except requests.exceptions.RequestException:
            return {}

