            shutil.copytree(self.docs_dir, version_dir)
            git_command = f'git add {version_dir} && git commit -m "Created version {version_name}"'
            self.git_repo.git.execute(git_command)

    def switch_version(self, version_name):
        version_dir = os.path.join(self.versions_dir, version_name)
        if os.path.exists(version_dir):
            shutil.rmtree(self.docs_dir)
            shutil.copytree(version_dir, self.docs_dir)
        else:
            print(f"Version {version_name} does not exist.")

    def track_changes(self):
        for commit in self.git_repo.iter_commits():
            print(f"Commit: {commit.hexsha} - {commit.message}")

    def create_doc(self):
        if not os.path.exists(self.docs_dir):
            os.makedirs(self.docs_dir)
            with open(os.path.join(self.docs_dir, 'index.md'), 'w') as file:
                file.write('# MkDocs Documentation')
        mkdocs_command = f'mkdocs build -d {self.docs_dir}'
        os.system(mkdocs_command)
