from django.contrib.auth.decorators import login_required
from django.shortcuts import render, get_object_or_404
from django.utils import timezone
from django.views.generic import ListView, CreateView, DeleteView
from.models import AuditLog

class LogListView(ListView):
    model = AuditLog
    template_name = 'audit_log/log_list.html'

class LogCreateView(CreateView):
    model = AuditLog
    fields = ('event_type', 'user', 'object_name', 'object_id', 'data')
    template_name = 'audit_log/log_create.html'

class LogDeleteView(DeleteView):
    model = AuditLog
    success_url = '/'
    template_name = 'audit_log/log_delete.html'

@login_required
def log_list(request):
    logs = AuditLog.objects.all()
    return render(request, 'audit_log/log_list.html', {'logs': logs})

@login_required
def log_list_by_type(request):
    event_type = request.GET.get('event_type')
    if event_type:
        logs = AuditLog.objects.filter(event_type=event_type)
    else:
        logs = AuditLog.objects.all()
    return render(request, 'audit_log/log_list.html', {'logs': logs})

@login_required
def log_list_by_date(request):
    start_date = request.GET.get('start_date')
    end_date = request.GET.get('end_date')
    if start_date and end_date:
        logs = AuditLog.objects.filter(timestamp__range=(start_date, end_date))
    else:
        logs = AuditLog.objects.all()
    return render(request, 'audit_log/log_list.html', {'logs': logs})

@login_required
def log_list_by_user(request):
    user_id = request.GET.get('user_id')
    if user_id:
        logs = AuditLog.objects.filter(user_id=user_id)
    else:
        logs = AuditLog.objects.all()
    return render(request, 'audit_log/log_list.html', {'logs': logs})

