def format_street_address(address):
    # Dictionary of common street directions
    directions = {
       'street': ['st', 'ave', 'blvd', 'rd', 'ln', 'dr', 'pl', 'ct'],
        'road': ['rd', 'road', 'avenue', 'boulevard', 'drive', 'lane', 'park','square'],
        'drive': ['dr', 'drive', 'avenue', 'boulevard','street', 'lane', 'park','square'],
        'avenue': ['ave', 'avenue', 'boulevard', 'drive', 'lane', 'park','square','street'],
        'boulevard': ['blvd', 'boulevard', 'drive', 'lane', 'park','square','street', 'avenue']
    }

    # Dictionary of numbered street suffixes
    numbers = {
        '1st': '1st',
        '2nd': '2nd',
        '3rd': '3rd',
        '4th': '4th',
        '5th': '5th',
        '6th': '6th',
        '7th': '7th',
        '8th': '8th',
        '9th': '9th',
        '10th': '10th'
    }

    # Parse address string
    words = address.split()

    # Find street name
    street_name = ''
    for word in words:
        if word.lower() in directions['street'] or word.lower() in directions['road'] or word.lower() in directions['drive'] or word.lower() in directions['avenue']:
            street_name = word
            break

    # Convert numbered street suffixes to numerical digits
    for i in range(len(words)):
        if words[i] in numbers:
            words[i] = str(numbers[words[i]])

    # Append direction to street name
    for word in words:
        if word.lower() in directions['street'] or word.lower() in directions['road'] or word.lower() in directions['drive'] or word.lower() in directions['avenue']:
            if street_name!= '':
                street_name +='' + word
            else:
                street_name = word

    # Reconstruct formatted address string
    formatted_address = ''
    for word in words:
        if word in numbers:
            formatted_address += word +''
        elif word.lower() in directions['street'] or word.lower() in directions['road'] or word.lower() in directions['drive'] or word.lower() in directions['avenue']:
            formatted_address += word +''
        else:
            formatted_address += word +''

    # Remove trailing spaces
    formatted_address = formatted_address.strip()

    return formatted_address

